css:
.eg-ans.eg-2 { grid-template-columns: repeat(2, 1fr); }
.jw-col { display: flex; flex-direction: column; gap: 8px; min-height: 0; align-items: center; }
.jw-wipe { position: relative; flex: 1 1 auto; min-height: 0; aspect-ratio: 498 / 870; max-width: 100%; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; cursor: ew-resize; touch-action: none; user-select: none; background: #000; }
.jw-wipe:focus-visible { outline: 4px solid var(--accent); outline-offset: 3px; }
.jw-wipe img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; pointer-events: none; }
.jw-h { position: absolute; top: 0; bottom: 0; left: calc(var(--k, .5) * 100%); width: 4px; margin-left: -2px; background: #ffd84d; box-shadow: 0 0 10px rgba(0,0,0,.6); }
.jw-h::after { content: '◀ ▶'; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); background: #ffd84d; color: #1d2433; font: 800 18px/1 var(--f-body); padding: 10px 8px; border-radius: 999px; white-space: nowrap; }
.jw-tag { position: absolute; top: 10px; font: 700 18px/1.2 var(--f-body); color: #fff; background: rgba(15,22,48,.75); padding: 4px 10px; border-radius: 8px; }
.jw-ta { left: 10px; } .jw-tb { right: 10px; }
.jw-cr { margin: 0; font: 600 17px/1.3 var(--f-body); color: var(--ink-2); }
.jw-cr small, .jw-tel small { font-size: 14px; color: var(--ink-3); }
.jw-tel { margin: 0; display: grid; grid-template-columns: 200px 1fr; gap: 14px; align-items: center; padding: 10px; }
.jw-tel img { width: 200px; height: 120px; object-fit: cover; border-radius: 8px; }
.jw-tel figcaption { font: 600 19px/1.4 var(--f-body); }
.jw-out { margin: 0; font: 500 20px/1.5 var(--f-body); min-height: 3em; }

